return [{json:{
  body:{
    client_name:"Entreprise Démo",
    email:"user@example.com",
    project_name:"Étude structure bâtiment A",
    project_type:"Structure",
    phone:"+1234567890",
    deadline:"2026-09-30",
    message:"Merci de confirmer la prise en charge."
  },
  source:"manual_test"
}}];

const src = $json.body ?? $json;
const clean = (v) => String(v ?? '').trim();
const required = ['client_name','email','project_name'];
const missing = required.filter(k => !clean(src[k]));
const email = clean(src.email).toLowerCase();
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
if (!validEmail && email) missing.push('email_invalid');
const stamp = new Date().toISOString().slice(0,10).replaceAll('-','');
const random = Math.random().toString(36).slice(2,6).toUpperCase();
return [{json:{
  valid: missing.length === 0,
  missing:[...new Set(missing)],
  project_id:`AFF-${stamp}-${random}`,
  client_name:clean(src.client_name), email,
  project_name:clean(src.project_name), project_type:clean(src.project_type || 'Non précisé'),
  phone:clean(src.phone), deadline:clean(src.deadline), message:clean(src.message),
  received_at:new Date().toISOString(), status:'NOUVEAU', source:clean($json.source || 'webhook')
}}];

